-- GENERATED by apps/web/supabase/gen/gen_syllabus_seed.py from seed-data/syllabus-mech-2023-24-pilot.json. Edit those, not this file.
-- Pilot: 10 Mechanical subjects, scheme 2023-24. Subjects and semesters are not created here: the PDF has no
-- semester table, so a subject page shows its syllabus once an offering with the same code exists.

insert into public.subject_syllabus (college_id, branch, code, name, scheme_year, ltp, credits_total, prerequisites, units, source_url, source_page, source_note)
select (select id from public.colleges where slug = 'sgsits'), v.* from (values
  ('Mech', 'ME46018', 'Automobile Engineering', '2023-24', '3-0-2', 4, 'ME 26005 and ME 36509', $u$[{"no":1,"text":"Vehicle Structure: Fine frame, integral body structure, engine, transmission and body structure mountings, sub frames collision safety, type of rubber flexible mounting.\nVehicle ride characteristics: human response, vehicle ride."},{"no":2,"text":"Handling System and Steering System: Study state handling characteristics and response to input. Steering gear box fundamental design. Need for power steering, steering linkages ball and socket joints.\nSuspension: Suspension geometry camber, Swivel & Castor angle. Suspension roll centres body roll stability. Antiroll stiffness. Rubber Spring pump or limiting stop. Axle location, front wheel drive, independent suspension, Macpherson stut & rear wheel. Hotchkiss drive springs & shock absorber."},{"no":3,"text":"Pneumatic Tyre: Mechanics of type forces, rolling resistance, tractive effort & step. Cornering properties & stiffness, Performance on roads. Tyre material & construction, Thread design & its marking identification.\nBrakes, Braking fundamentals, Brake shoe & pad fundamentals brake & shoe expander & adjuster disc brakes. Dual brake system, anti-locking brakes air operated power brakes."},{"no":4,"text":"Friction Clutch: Clutch fundamentals, Angular driven plate, Cushioning & torsional damping, Friction material, clutch alignment, types of clutch - diaphragm, multiplate etc., hydraulically operated automatic transmission clutch.\nElectrical System: Self-starting mechanism & battery charging system, Lighting & wiring system for horn, lamp indicators etc.\nGeneral: Air conditioning, auto inspection motor vehicle acts, emission standard & its control."},{"no":5,"text":"Transmission: The necessity for a Gear box, five speed and reverse synchromesh, Gear box synchronization & engagement, remote controlled gear selection & engagement, splitter & range change gear box, over drive considerations setting gear ratios, Hydrokinetic fluid coupling & torque converter, final drive transmission, crown wheel & pinion axle adjustment, differential locks, skid reducing universal joint, four wheel drive & two wheel drive.\nPerformance Characteristics of Road Vehicles: Tractive effort weight & axle loads, aerodynamics forces, vehicle power plant & transmission characteristics & its prediction operating fuel economy."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '39', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.'),
  ('Mech', 'ME46051', 'Vibration & Noise Control', '2023-24', '3-0-2', 4, 'ME 26002, ME 26562 and ME 36011', $u$[{"no":1,"text":"Introduction: Periodical motion, harmonic motion, the vector method of representing vibrations, displacement, velocity and acceleration in harmonic motion, work done in harmonic motion, superposition of simple harmonic motion, beat phenomenon, non harmonic periodic motions. Harmonic analysis.\nSystem having single degree of freedom, free vibration of systems without damping, Equilibrium and Energy Method for determining natural frequency. Reyleigh's Method, Equivalent Systems (systems with compound springs, shafts of different diameter Equivalent length, effects of mass of spring and shaft). Free vibration of systems with Viscous, Coulomb and Structural damping. Equations of motion - Discussion of its solutions."},{"no":2,"text":"Forced vibrations of systems with and without damping, Method of complex algebra, equivalent viscous damping, impressed force due to unbalance, transmissibility, support motion, Vibration isolation, commercial isolators.\nWhirling of shafts: Whirling of light flexible shaft with an unbalance disk at the centre of its length with and without damping, discussion of the speeds above and below the critical speed, uniform shaft with and without unbalanced masses attached along its length (by Reyleigh Method) for simply supported and fixed ends.\nVibration & Noise Measurement: Principle of frequency, amplitude, velocity and acceleration measuring instruments"},{"no":3,"text":"System with two-degree of freedom: Torsional systems, Degenerate Systems, Coupled vibrations, vehicle suspension, Undamped dynamic vibration absorber, Centrifugal absorber, friction damper.\nModal Analysis, Orthogonality of Eigenvectors, Decoupling of Equations of Motion, Modal Mass, Modal Stiffness and Modal Damping, General solution in terms of normal mode (Normal Mode Summation) Introduction to Experimental Modal Analysis"},{"no":4,"text":"Machine vibration data acquisition, Vibration Severity and Standards, analysis of vibration records, Vibration Monitoring.\nNoise and its causes, Subjective response to sound, sound pressure/ intensity/ power level and their inter-relation, Inverse Square Law, Decibel scale, Threshold of hearing, Audible Frequency Range, Sound wave propagation, Radiation Fields of Sound Source, Near field, Far field, Free field, Direct field, Reverberant field, Diffuse field, Loudness and equal loudness contours"},{"no":5,"text":"Noise Control: Effect of machine / process noise on operators, employees and local residents. Standards of noise level and exposure limits. Frequencies of interest and Frequency Weighting networks, Sound spectra and octave band analysis, 1/1 and 1/3 Octave filters. Background noise, Measurement of noise, Acoustic Chambers, Anechoic Chamber, Reverberation chamber,\nSound absorbing materials, Sound Absorption and Reflection Coefficients, Noise reduction coefficient, Methods of industrial noise control."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '41', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.'),
  ('Mech', 'ME46219', 'Advanced Machine Design', '2023-24', '3-0-0', 3, 'ME 26551 and ME 36503', $u$[{"no":1,"text":"Rotating ring and disks: Discs of uniform thickness and disc of uniform strength effect of drill hole and extra mass, design of flywheel and pulley, etc.\nDesign analysis of curved machine members: Crane hooks, chain link, open and close link, m/c frames."},{"no":2,"text":"Design of parts of unsymmetrical sections: Defining shear centre, parts subjected to unsymmetrical bending.\nLimit design analysis: Simple cases of deformations beyond elastic limits."},{"no":3,"text":"Reliability based design: Reliability based design of machine elements, design of elements subjected to tension, compression, bending and torsion.\nDesign of machine tool drives: Design of machine tool drives for different machines such as lathe, milling machine, drilling machine, etc."},{"no":4,"text":"Experimental method in design: Introduction to experimental stress analysis techniques.\nHuman factors in design: Introduction to human - machine system, human factors, applications in system design, human physical activities, human control of systems, shapes, coding of control."},{"no":5,"text":"Design of automotive gear box-manual and automatic"}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '45', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied. Unit labels in the PDF sit one line off their text; the split below follows the order of the five course outcomes.'),
  ('Mech', 'ME46218', 'Mechatronics and Automation', '2023-24', '3-0-0', 3, 'ME 36003', $u$[{"no":1,"text":"Control system and types: Open loop and closed loop control systems. Block Diagrams representation of control system. Laplace Transform and Transfer Function. Mathematical modeling of mechanical and electrical system. Poles and zeros. Zero order, first order and second order systems and their dynamic response."},{"no":2,"text":"Routh Hurwitz stability criteria, Introduction to bode plot and root locus method. Basic control actions. Proportional, integral and derivative control. Op Amp based PID controller, PID control using MATLAB. Combinatorial and sequential logic. Simple logic networks."},{"no":3,"text":"Electro-Mechanical Actuators: Electro-mechanical actuators, solenoids and relays, types of electric motors and their characteristics, electrical drives and control of electric motor.\nHydraulic & Pneumatic Systems: Hydraulic & Pneumatic cylinders and Actuators, Pressure and Flow Control Valves, Direction Control Valves, Basic circuit, Reference circuit, Meter-in, Meter-out and Bleed off circuit, Accumulator circuit, Circuit Diagram representation,"},{"no":4,"text":"Motion Control: Trajectory planning, motion controllers, point to point motion, co-ordinated multi-axis motion, electronic gearing,\nFeedback devices: linear and rotary encoders, resolvers, tachometers and tacho-generators."},{"no":5,"text":"Signal Conditioning & Data Acquisition: Amplification. Filters. Operational amplifier and its applications. Analog to digital conversion. Data acquisition. Introduction of microcontrollers interfacing with micro-controller and micro-processor."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '49', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.'),
  ('Mech', 'ME46671', 'Artificial Intelligence', '2023-24', '3-0-0', 3, null, $u$[{"no":1,"text":"Introduction: Concept of AI, history, current status, scope, agents, environments, Problem Formulations, Review of tree and graph structures, State space representation, Search graph and Search tree."},{"no":2,"text":"Search Algorithms: Random search, Search with closed and open list, Depth first and Breadth first search, Heuristic search, Best first search, A* algorithm, Game Search."},{"no":3,"text":"Probabilistic Reasoning: Probability, conditional probability, Bayes Rule, Bayesian Networks-representation, construction and inference, temporal model, hidden Markov model."},{"no":4,"text":"Markov Decision process: MDP formulation, utility theory, utility functions, value iteration, policy iteration and partially observable MDPs."},{"no":5,"text":"Reinforcement Learning: Passive reinforcement learning, direct utility estimation, adaptive dynamic programming, temporal difference learning, active reinforcement learning- Q learning."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '51', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.'),
  ('Mech', 'ME46315', 'Hydraulic, Pneumatic & Fluidic Control', '2023-24', '3-0-0', 3, 'ME 26011 and ME 36506', $u$[{"no":1,"text":"Characteristics of hydraulic components, control valves, sources of hydraulic power, hydraulic motors, cylinders,"},{"no":2,"text":"Elements of circuit design, accumulator, control circuits such as position control and speed control circuits, flow control methods, sequence operation, regenerative circuit"},{"no":3,"text":"Pneumatic systems and components, conditioning of compressed air, air lubricator, pressure regulators, filters, pneumatic cylinders and motors, cylinder cushioning."},{"no":4,"text":"Steady state analysis of pneumatic components and circuits, applications in industrial process control, proportional, derivative controllers etc."},{"no":5,"text":"Principles of fluidics, fluidic components, analogue and digital amplifiers and sensors, equivalent electric circuits, graphical characteristics, logic gates and applications."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '53', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.'),
  ('Mech', 'ME46327', 'Data Sciences', '2023-24', '3-0-0', 3, null, $u$[{"no":1,"text":"Introduction to Data Science: Concept of Data Science, Traits of Big data, Web Scraping, Analysis vs Reporting."},{"no":2,"text":"Introduction to Programming Tools for Data Science: (a) Toolkits using Python: Matplotlib, NumPy, Scikit-learn, NLTK (b) Visualizing Data: Bar Charts, Line Charts, Scatterplots (c) Working with data: Reading Files, Scraping the Web, Using APIs (Example: Using the Twitter APIs), Cleaning and Munging, Manipulating Data, Rescaling, Dimensionality Reduction"},{"no":3,"text":"Mathematical Foundations: (a) Linear Algebra: Vectors, Matrices, (b) Statistics: Describing a Single Set of Data, Correlation, Simpson's Paradox, Correlation and Causation (c) Probability: Dependence and Independence, Conditional Probability, Bayes's Theorem, Random Variables, Continuous Distributions, The Normal Distribution, The Central Limit Theorem (d) Hypothesis and Inference: Statistical Hypothesis Testing, Confidence Intervals, Phacking, Bayesian Inference."},{"no":4,"text":"Machine Learning: Overview of Machine learning concepts, Over fitting and train/ test splits, Types of Machine learning, Supervised, Unsupervised, Reinforced learning, Introduction to Bayes Theorem, Linear Regression model assumptions, regularization (lasso, ridge, elastic net), Classification and Regression algorithms- Naive Bayes, K-Nearest Neighbors, logistic regression, support vector machines (SVM), decision trees, and random forest, Classification Errors, Analysis of Time Series- Linear Systems Analysis, Nonlinear Dynamics, Rule Induction, Neural Networks Learning and Generalization, Overview of Deep Learning."},{"no":5,"text":"Case Studies of Data Science Application: Weather forecasting, Stock market prediction, Object recognition, Real Time Sentiment Analysis."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '55', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied. Unit labels in the PDF sit one line off their text; the split follows the order of the five blocks.'),
  ('Mech', 'ME46668', 'Renewable Energy Sources', '2023-24', '3-0-0', 3, 'ME 26005 and ME 36007', $u$[{"no":1,"text":"Energy and Environment: Primary energy sources, world energy resources, Indian energy scenario, energy cycle of the earth, environmental aspects of energy utilisation, CO2 emissions and Global warming, renewable energy resources and their importance. Potential impacts of harnessing the different renewable energy resources."},{"no":2,"text":"Solar Energy: Principles of solar energy collection, solar radiation, measurements, instruments, data and estimation, types of collectors, characteristics and design principles of different type of collectors, performance of collectors, testing of collectors. Solar thermal applications, water heaters and air heaters, performance and applications, simple calculations, solar cooling, solar drying, solar ponds, solar tower concept, solar furnace."},{"no":3,"text":"Wind energy Systems: Orientation systems and regulating devices, design of blades, Aerodynamic configuration of rotor and determination of blade structure, Description and performance of Vertical axis wind mills. Use of wind energy for water pumping and generation of electricity, Installation operation and maintenance of small wind energy conversion systems."},{"no":4,"text":"(a) Ocean Energy: Energy from tides and waves, working principles of tidal plants and ocean thermal energy conversion plants,\n(b) Geothermal Energy: Introduction to geothermal power, principle of working of geothermal power plants.\n(c) Hydel Energy: Small, mini and Micro hydro system, concepts, types of turbine, hydrological analysis."},{"no":5,"text":"Bio Energy: Energy from bio mass and bio gas plants, various types, design principles of biogas plants, applications. Energy from wastes, waste burning power plants, utilization of industrial and municipal wastes, energy from the agricultural wastes."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '61', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.'),
  ('Mech', 'ME46670', 'Finite Element Methods', '2023-24', '3-0-0', 3, 'ME 26002 and ME 36011', $u$[{"no":1,"text":"Solution to engineering problems, mathematical modeling, discrete and continuum modeling, need for numerical methods of solution, relevance and scope of finite element methods, engineering applications of FEA, Initial value and boundary value problems.\nWeighted residual methods, weak formulation of the weighted residual statement, principle of stationary total potential, Rayleigh Ritz method."},{"no":2,"text":"1-D Elements: Formulation for 1-D applications, linear bar element, quadratic element, shape functions. Application to thermal and fluid flow problems"},{"no":3,"text":"Beam element, thin beam approximation, Euler Bernoulli's beam element, Shear locking, Timoshenko beam element for thick beam, shape functions, Applications to truss and frame problems."},{"no":4,"text":"2-D Analysis: triangular, rectangular and quadrilateral elements, higher order elements, natural coordinates and coordinate transformations, iso-parametric formulation, plane stress and plane strain problems, axi-symmetric problems, Gausss quadrature formula, natural coordinates,"},{"no":5,"text":"DYNAMIC ANALYSIS: vibration problems, equations of motion, longitudinal vibration of bars, consistent mass matrices, eigenvalue problems, normal modes, forced vibration, transient vibrations, modeling of damping, mode superposition technique."}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '63', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.'),
  ('Mech', 'ME46706', '3D Printing And Design', '2023-24', '3-0-0', 3, null, $u$[{"no":1,"text":"CAD for Additive Manufacturing: CAD Data formats, Data translation, Data loss, STL file format & its importance\n3D Printing (Additive Manufacturing): Introduction, Process, Classification, Advantages, Additive v/s Conventional Manufacturing processes, Applications."},{"no":2,"text":"Additive Manufacturing Techniques:\n- Process, Process parameter, Process Selection for various applications.\n- Additive Manufacturing Application Domains: Aerospace, Electronics, Health Care, Defence, Automotive, Construction, Food Processing, Machine Tools\n- Stereo-Lithography, LOM, FDM, SLS, SLM, Binder Jet technology."},{"no":3,"text":"Materials:\n- Polymers, Metals, Non-Metals, Ceramics\n- Various forms of raw material- Liquid, Solid, Wire, Powder; Powder Preparation and their desired properties, Polymers and their properties.\n- Support Materials"},{"no":4,"text":"Additive Manufacturing Equipment:\n- Process Equipment- Design and process parameters, Laser in additive manufacturing.\n- Governing Bonding Mechanism\n- Common faults and troubleshooting\n- Process Design"},{"no":5,"text":"Post Processing: Requirement and Techniques\nProduct Quality\n- Inspection and testing\n- Defects and their causes"}]$u$::jsonb, 'https://web.archive.org/web/20250913202115/https://www.sgsits.ac.in/files/Syllabus_2023-24_BTech_Mechanical_Engg.pdf', '72', 'Internet Archive copy of the official PDF. The cover says 2023-24; each page header says 2022-23. Unit wording is the PDF''s, spacing and obvious typos tidied.')
) as v(branch, code, name, scheme_year, ltp, credits_total, prerequisites, units, source_url, source_page, source_note)
on conflict (college_id, branch, code, scheme_year) do nothing;
